local function slug(name)
    return (name:lower():gsub('[^%w]+', '_'):gsub('^_+', ''):gsub('_+$', ''))
end

Config.Garages = Config.Garages or {}
for _, g in ipairs(extra) do
    Config.Garages[#Config.Garages + 1] = {
        id      = slug(g.name),
        label   = g.name,
        coords  = vec4(g.menu.x, g.menu.y, g.menu.z, g.spawn.w),
        preview = g.preview,
        spawn   = g.spawn,
        blip    = { sprite = 357, color = 3, scale = 0.5, label = 'Garage' },
    }
end
